sp_widget.client_script:
api.controller = function($http, $window, spUtil) { 

    var c = this; 

    c.email = ""; 
    c.password = ""; 
    c.message = ""; 
    c.isLoggingIn = false; 

    c.login = function() { 

        if (c.isLoggingIn) { 
            return; 
        } 

        if (!c.email) { 
            c.message = "Please enter your email address."; 
            return; 
        } 

        if (!c.password) { 
            c.message = "Please enter your password."; 
            return; 
        } 

        c.message = ""; 
        c.isLoggingIn = true; 

        var url = spUtil.getURL({ 
            sysparm_type: "view_form.login" 
        }); 

        $http({ 
            method: "post", 
            url: url, 
            data: $.param({ 
                sysparm_type: "login", 
                "ni.nolog.user_password": true, 
                remember_me: false, 
                user_name: c.email, 
                user_password: c.password, 
                get_redirect_url: true, 
                is_direct_redirect: true, 
                sysparm_goto_url: null, 
                mfa_redirect_url: null, 
                cert_login: false 
            }), 
            headers: { 
                "Content-Type": 
                    "application/x-www-form-urlencoded" 
            } 
        }).then(function(response) { 

            // =========================================
            // AUTHENTICATION SUCCESS
            // =========================================

            if ( 
                response.data && 
                response.data.status === "success" 
            ) { 

                // =========================================
                // CHECK EVENT ORGANIZER PROFILE
                // =========================================

                c.server.get({ 
                    action: "check_organizer" 
                }).then(function(organizerResponse) { 

                    var result = organizerResponse.data; 

                    // =========================================
                    // ORGANIZER PROFILE FOUND
                    // =========================================

                    if (result.organizerExists) { 

                        c.isLoggingIn = false; 
                        c.message = ""; 

                        $window.location.href = 
                            "?id=event_organizer_dashboard"; 

                        return; 
                    } 

                    // =========================================
                    // ORGANIZER PROFILE NOT FOUND
                    // =========================================

                    c.isLoggingIn = false; 
                    c.password = ""; 

                    c.message = 
                        result.message || 
                        "This account is not registered as a Campus Connect Event Organizer."; 

                    // =========================================
                    // LOG OUT NON-ORGANIZER USER
                    // =========================================

                    $http({ 
                        method: "get", 
                        url: "/logout.do" 
                    }).finally(function() { 

                        $window.location.href = 
                            "?id=campus_organizer_login"; 

                    }); 

                }, function() { 

                    c.isLoggingIn = false; 
                    c.password = ""; 

                    c.message = 
                        "Unable to verify your Event Organizer profile."; 

                }); 

                return; 
            } 

            // =========================================
            // INVALID CREDENTIALS
            // =========================================

            c.isLoggingIn = false; 
            c.password = ""; 

            c.message = 
                ( 
                    response.data && 
                    response.data.message 
                ) || 
                "Invalid email or password."; 

        }, function() { 

            c.isLoggingIn = false; 
            c.password = ""; 

            c.message = 
                "Unable to process your login request. Please try again."; 

        }); 

    }; 


    c.forgotPassword = function() { 

        $window.location.href = 
            "$pwd_reset.do?sysparm_url=ss_default"; 

    }; 


    c.createAccount = function() { 

        $window.location.href = 
            "?id=campus_organizer_signup"; 

    }; 

};

sp_widget.css:
.organizer-login-page {

    min-height: 100vh;

    display: flex;

    align-items: center;

    justify-content: center;

    padding: 40px 20px;

    background:

        radial-gradient(
            circle at 15% 20%,
            rgba(37, 99, 235, 0.12),
            transparent 30%
        ),

        radial-gradient(
            circle at 85% 80%,
            rgba(30, 64, 175, 0.12),
            transparent 30%
        ),

        linear-gradient(
            135deg,
            #ffffff,
            #eff6ff,
            #dbeafe
        );

    font-family:
        Arial,
        sans-serif;

}


.login-card {

    width: 100%;

    max-width: 430px;

    padding: 40px;

    background: #ffffff;

    border-radius: 22px;

    box-shadow:
        0 20px 50px
        rgba(30, 64, 175, 0.15);

    border: 1px solid #bfdbfe;

    text-align: center;

}


.login-icon {

    width: 70px;

    height: 70px;

    margin: 0 auto 20px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background: #dbeafe;

    color: #1d4ed8;

    font-size: 35px;

    box-shadow:
        0 8px 20px
        rgba(37, 99, 235, 0.12);

}


.login-card h1 {

    margin: 0;

    font-size: 30px;

    font-weight: 800;

    color: #0f3d91;

}


.login-subtitle {

    margin: 10px 0 30px;

    color: #475569;

    font-size: 14px;

}


.form-group {

    text-align: left;

    margin-bottom: 20px;

}


.form-group label {

    display: block;

    margin-bottom: 8px;

    font-size: 14px;

    font-weight: 600;

    color: #1e3a8a;

}


.form-control {

    width: 100%;

    height: 48px;

    padding: 0 14px;

    border: 1px solid #bfdbfe;

    border-radius: 10px;

    background: #ffffff;

    color: #0f172a;

    font-size: 14px;

    box-sizing: border-box;

    outline: none;

    transition: 0.2s;

}


.form-control::placeholder {

    color: #94a3b8;

}


.form-control:focus {

    border-color: #2563eb;

    background: #ffffff;

    box-shadow:
        0 0 0 3px
        rgba(37, 99, 235, 0.12);

}


.login-submit {

    width: 100%;

    height: 50px;

    margin-top: 8px;

    border: none;

    border-radius: 10px;

    background:
        linear-gradient(
            135deg,
            #1d4ed8,
            #2563eb
        );

    color: #ffffff;

    font-size: 16px;

    font-weight: 700;

    cursor: pointer;

    transition: 0.25s;

    box-shadow:
        0 8px 20px
        rgba(37, 99, 235, 0.20);

}


.login-submit:hover {

    transform: translateY(-2px);

    background:
        linear-gradient(
            135deg,
            #1e40af,
            #1d4ed8
        );

    box-shadow:
        0 10px 22px
        rgba(37, 99, 235, 0.30);

}


.login-submit:active {

    transform: translateY(0);

}


.login-submit:disabled {

    opacity: 0.65;

    cursor: not-allowed;

}


.login-links {

    margin-top: 25px;

    font-size: 13px;

    color: #64748b;

}


.login-links a {

    color: #2563eb;

    text-decoration: none;

    font-weight: 600;

    transition: 0.2s;

}


.login-links a:hover {

    color: #1e40af;

    text-decoration: underline;

}


@media (max-width: 500px) {

    .organizer-login-page {

        padding: 20px 12px;

    }


    .login-card {

        padding: 30px 22px;

    }


    .login-card h1 {

        font-size: 26px;

    }

}

sp_widget.script:
(function() {

    data.organizerExists = false;
    data.message = "";


    /* =====================================================
       CHECK WHETHER LOGGED-IN USER IS AN ORGANIZER
       ===================================================== */

    if (
        input &&
        input.action === "check_organizer"
    ) {

        var userId =
            gs.getUserID();


        if (!userId) {

            data.organizerExists = false;

            data.message =
                "User is not authenticated.";

            return;
        }


        /* =====================================================
           FIND EVENT ORGANIZER PROFILE
           ===================================================== */

        var organizer =
            new GlideRecord(
                "x_snc_campus_con_0_event_organizers"
            );


        /*
         * Organizer Name is the reference field
         * that points to sys_user.
         */

        organizer.addQuery(
            "organizer_name",
            userId
        );

        organizer.addQuery(
            "verification_status",
            "verified"
        );

        organizer.setLimit(1);

        organizer.query();


        if (organizer.next()) {

            data.organizerExists =
                true;

            data.message =
                "Event Organizer profile found.";

        } else {

            data.organizerExists =
                false;

            data.message =
                "This account is not registered as a Campus Connect Event Organizer.";
        }


        return;
    }

})();
